package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaDoiDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_breaking_fast" to DuaText("व्रत तोड़े जाने पर", "प्यास चली गेई ऐ, नसें गी नम करी दित्ता गेआ ऐ, ते जे अल्लाह चाहे तां इनाम दी पुश्टी होई जंदी ऐ।", "इफ्तार दे समें।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने अपना रोजा तोड़ींदे होई एह् आखेआ।"),
        "dua_new_clothes" to DuaText("नमें कपड़े पहनें", "ऐ अल्लाह, सारी स्तुति तेरी ऐ, तुस मिगी एह् वस्त्रा पाई दित्ता ऐ। में तुंʼदे शा एह्दे भले आस्तै ते एह्दे भले आस्तै मंगदा आं, ते में तुंʼदे च एह्दे बुरे ते बुरे आस्तै शरण लैंदा आं।", "नमां कपड़ा पहिनदे समें (इसगी नांऽ दित्ता जाना, जिʼयां कि कमीज जां पग्ग)।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने नमां कपड़ा पहिनदे होई एह् दुआ बनाई। (कपड़े पहनने आस्तै दैनिक दुआ'कपड़े पहिनने'दे तैह्त ऐ।)"),
        "dua_rabbana_atina" to DuaText("इस दुनिया ते आख़िरत च चंगा ऐ", "ऐ हमारे रब, असां गी इस दुनिया च चंगा ते आख़िरत च चंगा देओ, ते सानू अग्नी दी सज़ाया शा बचाओ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने सभनें शा मता दुआ कीती।", "इक दुआ जेह्ड़ी इस दुनिया ते आख़िरत दी हर भलाई गी इकट्ठी करदी ऐ।"),
        "dua_rabbi_zidni_ilma" to DuaText("ज्ञान च बधोआS", "हे मेरे प्रभु, मिगी ज्ञान च बधो।", "ज्ञान च वृद्धि आस्तै।", "अल्लाह ने पैगंबर सल्लल्लाहु अलैहि वसल्लम गी हुकम दित्ता जे ओह् ज्ञान दे अलावा होर किश नेईं मंगने।"),
        "dua_musa_sharh_sadr" to DuaText("छाती दा खु'लना (मूसा ए. ऐस्स.)", "हे मेरे प्रभु, मेरे लेई मेरी छाती दा विस्तार करो, मेरे आस्तै मेरा कम्म सौखा करो, ते मेरी जीभ दी गांठ तोड़ो तां जे ओह् मेरी गल्ल गी समझी सकण।", "परख शा पैह्लें, इक भाषण जां कोई औखे कम्म।", "पैगंबर मूसा (ए. ऐस्स.) दी दुआ-मन दी शांति ते अपने कम्म च आसानी।"),
        "dua_la_tuzigh" to DuaText("दिल दी स्थिरता", "ऐ हमारे रब, तुंʼदे मार्गदर्शन दे परैंत्त असां दे दिलें गी मत भटकाओ ते अपने आसेआ हमें पर रहम करो। निश्चय गै तुस गै दाता ओ।", "मार्गदर्शन पर दृढ़ता आस्तै।", "विश्वास च द्रिढ़ बने रहने आस्तै इक दुआ।"),
        "dua_ya_muqallib" to DuaText("ओ टर्नर ऑफ हार्ट्स", "हे दिल दे टर्नर, अपने धर्म पर मेरा दिल द्रिढ़ रक्खेआ करो।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम अक्सर एह् दुआ करदे हे।", "उम्म सलाम (र) दे मताबक, पैगंबर सल्लल्लाहु अलैहि वसल्लम ने सभनें शा मती दुआ कीती।"),
        "dua_la_tuakhidhna" to DuaText("सूरह अल-बकाराह दे आखरी छंद", "ऐ ऐ हमारे रब, जे असीं भुग्गियां जां कोई गलती करी जाईए तां असां पर कोई बी तौह्ज़ा नेईं लाओ। ऐ हमारे रब, साडे पर नेहा बोझ नेईं लाओ जेह्ड़ा तुस हमसे पैह्लें दे लोकें पर रक्खेआ हा। ऐ हमारे रब, असां पर नेहा बोझ नेईं लाओ जेह्ड़ा असीं नेईं लेई सकदे। सानू गी माफ़ करी देओ, सानू गी माफ़ करो ते साडे पर रहम करो। तुस हमारे रक्षक ओ, इस करियै इनकार करने आह्ले लोकें दे खलाफ साडी मदद करो।", "राती सोने शा पैह्लें-सूरह अल-बकाराह दे आखरी दो छंद।", "जेह्ड़ा कोई राती सूरह अल-बकाराह दे आखरी दो छंदें दा पाठ करदा ऐ, ओह् ओह्दे आस्तै काफी होग।"),
        "dua_visiting_sick" to DuaText("बीमारें दा दौरा करना", "में शक्तिशाली, शक्तिशाली संघासन दे स्वामी, अल्लाह कोला विनती करदा आं जे ओह् तुसें गी चंगा करे।", "स'त्तें बारी जिसलै बीमारें कोल जाईऐ।", "जे मौत दा समां नेईं आया ऐ, तां अल्लाह उसी चंगा करी देग।"),
        "dua_ruqyah_pain" to DuaText("शारीरिक पीड़ आस्तै", "में जेह्ड़ा अनुभव करदा आं ते जेह्ड़ा डरदा आं, ओह्दे बुरे असरें शा में अल्लाह ते ओह्दे बल दी शरण लैंदा आं।", "जित्थै दुखदा ऐ, ओह्दे पर अपना हाथ लाओ, त्रै बारी बिस्मिल्लाह, फ्ही सत्त बारी एह् दुआ करो।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने उथमन इब्न अबिल -'अस (रा.) गी पीड़ आस्तै एह् सिखाया।"),
        "dua_ruqyah_nabawi" to DuaText("बीमारें आस्तै भविष्यसूचक रुकिया", "ऐ अल्लाह, इंसानें दे रब! नुकसान गी दूर करो ते इलाज करो, तुस गै ठीक करने आह्ले ओ; तुंʼदे इलाज दे अलावा कोई इलाज नेईं ऐ-इक इलाज जेह्ड़ा कोई बी बीमारी गी नेईं छड़ेआ।", "बीमार व्यक्ति पर हथ बधांदे होई।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने अपने परोआर दे बीमार सदस्यें कन्नै मिलने दे दुरान एह् पढ़ा।"),
        "dua_kalimat_tammat" to DuaText("परिपूर्ण शब्दें च शरण दी भाल करना", "में अल्लाह दे सच्चें वचनें च उंʼदी बनाई दी बुराई थमां पनाह लैंदा आं।", "जिसलै कुसै थाह्र पर जां सʼञै रुकदे ओ।", "जेह्ड़ा कोई बी कुसै थाह्र पर रुकदा ऐ ते एह् आखदा ऐ, जिसलै तक्कर ओह् इसगी नेईं छोड़ी दिंदा, उसलै तक्कर ओह्दे लेई किश बी नुकसान नेईं होग।"),
        "dua_evil_eye" to DuaText("ञ्याणें आस्तै सुरक्षा (बुरी आंख)", "में हर इक शैतान ते हर इक ज़हरीले प्राणी कोला ते हर इक नुकसानदेह नज़र शा तुंʼदे दौनें आस्तै अल्लाह दे सटीक शब्दों च सुरक्षा मंगदा आं।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने हसन ते हुसैन (र) दे बारे च एह् पढ़ा।", "ञ्याणें गी बुरी नज़र ते नुकसान कोला बचाने आस्तै इक सुन्नत दुआ (इक ञ्याणे आस्तै'उधुका'आखेआ जंदा ऐ)।"),
        "dua_seeing_afflicted" to DuaText("कुसै गी मुक़दमे च दिक्खेआ जाना", "सारी स्तुति अल्लाह आस्तै ऐ जिʼन्नै तुसें गी परखने आह्ली चीज थमां मिगी बख्शिआ ऐ ते अपनी रचना दे जैदातर हिस्से पर मुझ पर कृपा कीती ऐ।", "कुसै गी मुकद्दमे च देखने पर (अपने आप गी चुपचाप दस्सो)।", "जेह्ड़ा आखदा ऐ जे एह् उस मुकदमे शा सुरक्खत ऐ।"),
        "dua_istikhara" to DuaText("सलात अल-इस्तिखारा", "ऐ अल्लाह, में तेरे ज्ञान दे राहें अच्छाई दी तलाश करदा आं, में तेरी शक्ति दे राहें सामर्थ्य दी भाल करदा आं, ते में तेरे कोला बड़ा उदारता दी मंग करदा आं। तेरे कोल शक्ति ऐ ते मेरे कोल कोई नेईं ऐ। तू जानदी ऐ ते में नेईं, ते तू अदृश्यें गी जानदी ऐ। हे अल्लाह, जे तेरी जानकारी च एह् मामला (मन च लाओ) मेरे धर्म, मेरे जीवन ते मेरे अंत आस्तै चंगा ऐ, तां मेरे लेई एह् हुकम करो, मेरे लेई एह् सौखा बनाओ ते मिगी एह्दे च बरकत देओ। ते जे तेरे ज्ञान च एह् मामला मेरे धर्म, मेरे जीवन ते मेरे अंत आस्तै बुरा ऐ, तां इसगी मेरे कोला दूर करी देओ ते मिगी एह्दे शा दूर करी देओ, ते मेरे लेई जित्थै बी चंगा होई सकदा ऐ, ओह्दे आस्तै हुकम देओ, फ्ही मिगी एह्दे कन्नै संतुष्ट करो।", "स्वैच्छिक प्रार्थना दे द'ऊं रक्क'ह दे परैंत्त, इजाज़त आह्ले मामले च सभनें शा चंगा केह् ऐ, एह् तुप्पना।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने साथी गी सारे मामलें च इस्तिकारा सिखाया की जे उʼनें उʼनें गी कुरान दी इक सूरह सिखाई ही।"),
        "dua_allahumma_bika_asbahna" to DuaText("अल्लाहुम्मा बीका असबाहना", "हे अल्लाह, असीं तुंʼदे राहें भ्यागा दाखल होंदे न ते तुंʼदे राहें सʼजैं दाखल होंदे न; तुंʼदे राहें हम जींदे न ते तुंʼदे राहें हम मरदे न, ते तुंʼदे लेई जी उठना ऐ।", "भ्यागा।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने साथी गी अज्ज भ्यागा ते सʼञै आखना सिखाया।"),
        "dua_allahumma_bika_amsayna" to DuaText("अल्लाहुम्मा बीका अम्सेना", "हे अल्लाह, असीं सʼञै च तुंʼदे राहें दाखल होंदे आं ते तुंʼदे राहें भ्यागा दाखल होंदे न; तुंʼदे राहें हम जींदे न ते तुंʼदे राहें हम मरदे न, ते तुंʼदे बक्खी बापस जाना ऐ।", "सʼञै दा।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने साथी गी अज्ज भ्यागा ते सʼञै आखना सिखाया।"),
        "dua_afiyah_morning" to DuaText("अफिया दी मंग करना", "हे अल्लाह, में तुंʼदे शा इस दुनिया ते आख़िरत च क्षमा ते कल्याण दी मंग करदा आं।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने कदें बी इस दुआ गी, भ्यागा जां सʼजलै नेईं छोड़ी।", "कुसै गी बी कल्याण कोला चंगा किश नेईं दित्ता गेआ ऐ।"),
        "dua_afini_fi_badani" to DuaText("शरीर, सुनने ते देखने दी तंदुरुस्ती", "ऐ अल्लाह, मेरे शरीर गी कल्याण देओ। ऐ अल्लाह, मेरी सुनवाई गी कल्याण देओ। ऐ अल्लाह, मेरी नज़र गी कल्याण देओ। तेरे बगैर कोई पूज्य-प्रभु नेईं ऐ।", "हर भ्यागा ते सʼञै त्रै बारी।", "स्वास्थ ते इंद्रियें दी सुरक्षा आस्तै इक दुआ।"),
        "dua_ya_hayyu_aslih" to DuaText("मेरे सारे मामलें गी ठीक करो", "हे सदाबहार, हे पालनकर्ता, में तुंʼदी दया कन्नै मदद मंगदा आंः मेरे सारे मामलें गी ठीक करो ते मिगी इक पलक बी अपने पर नेईं छडो।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने फातिमा (र.) गी एह् सकाल ते सʼञै कहने दी सलाह् दित्ती।", "हर मामले च अल्लाह दी मदद मंगना।"),
        "dua_subhanallah_adada_khalqihi" to DuaText("जुवेरिया दा तसबीह (आर. ए.)", "महिमावान ऐ अल्लाह ते सारी स्तुति ओह्दे लेई ऐ-जिʼयां उंʼदी रचना, जिʼयां उʼनें गी पसंद ऐ, उंʼदे संघासन दे भार ते उंʼदे वचनें दी स्याही दे बराबर।", "त्र'ऊं बारी भ्यागा-घंटो दे दिकर दी तुलना च भारी।", "इʼनें चार वाक्यांशें गी त्रै बारी कहने कन्नै भोर थमां मध्य भ्यागा तक्कर दिकर शा मता होंदा ऐ।"),
        "dua_salawat" to DuaText("दुरूद-ए-इब्राहिम", "ऐ अल्लाह, मुहम्मद सल्लल्लाहु अलैहि वसल्लम ते मुहम्मद दे परोआर पर नमाज़ भेजो जिʼयां तुस इब्राहिम (अ. स.) ते इब्राहिम दे परोआर पर नमाज़ भेजी; तुस काबले-तारीफ, महिमावान ओ। हे अल्लाह, मुहम्मद सल्लल्लाहु अलैहि वसल्लम ते मुहम्मद दे परोआर गी बरकत देओ जिʼयां तुस इब्राहिम (अ. स.) ते इब्राहिम दे परोआर गी बरकत दित्ती; तुस बरकत दे लायक, महिमावान ओ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम पर हर समें ते हर समें प्रार्थना च सलाम।", "जेह्ड़ा इक बारी सलावत भेजदा ऐ, अल्लाह ओह्दे पर दस बरकत भेजदा ऐ (मुसलमान 408)।"),
        "dua_wudu_after" to DuaText("वुडू दे परैंत्त", "में गवाही दिंदा आं जे कुसै गी बी पूजा करने दा हक्क नेईं ऐ छड़ा अकेले अल्लाह गी, बगैर साझीदार दे, ते मुहम्मद सल्लल्लाह् रसूल उंʼदे दास ते रसूल न। ऐ अल्लाह, मिगी पश्चाताप करने आह्ले ते अपने आप गी शुध्द करने आह्ले लोकें च शामल करो।", "वूडू पूरा करने दे परैंत्त।", "उंʼदे आस्तै स्वर्ग दे अट्ठ दरवाजे खु'ल्ले दे न जे ओह् जेह्ड़ा चाहे दाखल होई सकदे न।"),
        "dua_wudu_before" to DuaText("वुडू शा पैह्लें", "अल्लाह दे नांऽ पर।", "जिसलै वूडू शुरू कीता जंदा ऐ।", "जेह्ड़ा एह्दे उप्पर अल्लाह दे नांऽ दा जिकर नेईं करदा ऐ, ओह्दे आस्तै कोई (पूर्ण) वुडू नेईं ऐ।"),
        "dua_istiftah" to DuaText("खुʼल्ली प्रार्थना (सना)", "महिमा ऐ, हे अल्लाह, ते स्तुति ऐ तेरी। तेरा नांऽ बरकत आह्ला ऐ, तेरी महिमा महान ऐ, ते तेरे बगैर कोई पूज्य-प्रभु नेईं ऐ।", "नमाज़ दी शुरुआत च, उद्घाटन तक्बीर दे ठीक परैंत्त।", "सुन्नत कन्नै नमाज़ दी दुआ शुरू होंदी ऐ।"),
        "dua_ruku" to DuaText("रुकू च", "मेरे महान प्रभु दी महिमा ऐ।", "रुकू च घट्ट कोला घट्ट त्रै बारी।", "रुकू दा सुन्नत तसबिह।"),
        "dua_sujood" to DuaText("सुजूद च", "मेरे परम उच्च प्रभु दी महिमा ऐ।", "सुजूद च घट्ट कोला घट्ट त्रै बारी।", "सज्जा करदे होई नौकर अपने प्रभु दे सभनें शा नेड़मा होंदा ऐ (मुसलमान 482)।"),
        "dua_rising_ruku" to DuaText("रुकू थमां उठी दा", "अल्लाह उसी गी सुणदा ऐ जेह्ड़ा ओह्दे दी स्तुति करदा ऐ। ऐ हमारे रब, सारी स्तुति तेरी ऐ।", "रुकू थमां उठी दे ते खʼल्ल खʼल्ल खड़े होई।", "जिस कुसै दे'रब्बाना वा लकल-हमद'गी दूतां दे पापें कन्नै मेल कीता जंदा ऐ, ओह्दे पिछले पाप माफ करी दित्ता जंदा ऐ।"),
        "dua_between_sajdas" to DuaText("दौनें सजदासें दे बिच्च", "ऐ मेरे प्रभु, मिगी माफ करी देओ। ऐ मेरे प्रभु, मिगी माफ करी देओ।", "दौनें सजदा दे बिच्च बैठे दे।", "सजदा दे बिच्च बैठे दा सुन्नत दुआ।"),
        "dua_before_salam_four" to DuaText("चार चीजें शा शरण (सलाम शा पैह्लें)", "हे अल्लाह, में नरक दी सज़ाया, क़ब्र दी सज़ाया, जीवन ते मौत दी अज़माइशें ते झूठे मसीहा (दज्जल) दी अज़माइश दी बुराई थमां तुंʼदे च शरण मंगदा आं।", "आखरी ताशाहुद ते सलावत दे परैंत्त, सलाम शा पैह्लें।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने इʼनें चार चीजें थमां पनाह लैने दा हुकम दित्ता।"),
        "dua_qunoot_witr" to DuaText("विटर च कुनूट", "ऐ अल्लाह, जिʼनें गी तुस मार्गदर्शन दित्ता ऐ, उंʼदे च मेरा मार्गदर्शन करो, उʼनें च जेह्ड़ा तुस चंगा कीता ऐ, उंʼदे च मिगी चंगा करो, उʼनें च जेह्ड़ा तुस अपनी देखरेख च लाए ओ, उʼनें च मिगी अपनी देखभाल च लेई जाओ, जेह्ड़ा तुस दित्ता ऐ, ओह्दे च मिगी बरकत देओ, ते जेह्ड़ा तुस हुकम दित्ता ऐ, ओह्दे बुरे शा मिगी बचाओ। तुस हुकम दिंदे ओ ते तुंʼदे खलाफ कोई हुकम नेईं ऐ, ते जिस कन्नै तुस दोस्ती करदे ओ, ओह् कदें बी अपमानित नेईं होंदा। हे हमारे रब, तुस बरकत ते महान ओ।", "विदर नमाज़ च-पैगंबर सल्लल्लाहु अलैहि वसल्लम ने हसन इब्न अली (र.) गी एह् सिखाया।", "विदर दा सुन्नत कुनूट (हनाफियें च,'अल्लाहुम्मा इन्ना नस्ताइनुका'बी मश्हूर ऐ।)"),
        "dua_qunoot_hanafi" to DuaText("कुनूत (अल्लाहुम्मा इन्ना नस्ताइनुका)", "ऐ अल्लाह, असीं तेरी मदद ते तेरी क्षमा दी मंग करदे आं, असीं तेरे पर विश्वास करदे आं ते तेरे पर भरोसा करदे आं, असीं सभनें शा अच्छे तरीके कन्नै तेरी स्तुति करदे आं, असीं तेरा शुक्रगुजार आं ते कृतघ्न नेईं आं, ते जेह्ड़ा तेरी अवज्ञा करदा ऐ, उसी हम छड्डदे न। हे अल्लाह, हे खुदा, असीं इकले तेरी पूजा करदे न, तेरी पूजा करदे न ते सिजदा करदे न, तेरी बक्खी असीं जल्दी करदे न ते जतन करदे न, तुसें दी दया दी आशा करदे न ते तेरी सजा दा डर रखदे न; निश्चय गै तेरी सजा इनकार करने आह्ले तक्कर पुजङन।", "विटर च-हनाफियें दा अभ्यास।", "कुनूत च उमर (र.) थमां रिपोर्ट कीता गेआ।"),
        "dua_sleep_aslamtu" to DuaText("सौने शा पैह्लें आखरी शब्द", "ऐ अल्लाह, में अपने आप गी तेरे मतैह्त करी ओड़ेआ ऐ, अपना मामला तेरे कोल सुपुर्द करी ओड़ेआ ऐ ते तेरी सुरक्षा आस्तै अपनी पिट्ठ समर्पण करी दित्ती ऐ, तेरे पर आशा ते तेरे डर कन्नै। तेरे बगैर कोई पनाह ते कोई बच-बच नेईं ऐ। में तेरी किताब ते तेरे पैगंबर, जिस्सी तुस भेजेआ, पर विश्वास करदा आं।", "वूडू दे परैंत्त, सज्जे पासे पर लेटना-सोने शा पैह्लें खीरले शब्द।", "जे ओह् उस राती मरदा ऐ, तां ओह् फित्राह (इस्लाम) पर मरदा ऐ।"),
        "dua_waking_night" to DuaText("राती जागना", "कुसै गी बी पूजा करने दा अधिकार नेईं ऐ, छड़ा अल्लाह गी, बगैर साझीदार दे। शासन उसी दा ऐ ते स्तुति उसी दी ऐ, ते हर चीज पर उंʼदे कोल अधिकार ऐ। सारी स्तुति अल्लाह आस्तै ऐ, महिमा अल्लाह दी ऐ, अल्लाह दे अलावा कुसै गी बी पूजा करने दा अधिकार नेईं ऐ। अल्लाह सभनें शा बड़ा ऐ, ते अल्लाह दे अलावा कोई शक्ति जां शक्ति नेईं ऐ। ऐ अल्लाह, मिगी माफ करी देओ।", "राती जागने पर।", "उंʼदी दुआ दा जवाब दित्ता जंदा ऐ, ते जे ओह् वुडू करदा ऐ ते प्रार्थना करदा ऐ, तां उंʼदी प्रार्थना मंजूर कीती जंदी ऐ।"),
        "dua_hamm_ibn_masud" to DuaText("दुएं आस्तै दुआ (इब्न मसूद)", "हे अल्लाह, में तेरा सेवक आं, तेरे दास दा पुत्तर, तेरी दासी दा पुत्तर। मेरा अग्र-ताला तेरे ह'ते ऐ, तेरा मुझ पर हुकम पूरा होआ ऐ, ते मेरे बारे च तेरा हुकम ठीक ऐ। मैं तुंʼदे हर उस नांऽ कन्नै तुंʼदा पुच्छदा आं, जेह्दे कन्नै तुस अपना नांऽ लैता ऐ, जां अपनी किताब च प्रकट कीता ऐ, जां अपनी कुसै बी सृष्टि गी सिखाया ऐ, जां अपनी अनदेखी दे ज्ञान च अपने कन्नै रक्खेआ ऐ-जे तुस कुरान गी मेरे दिल दा झरना, मेरी छाती दा चानण, मेरे दुख गी दूर करना ते मेरी चिंता गी छोड़ना बनाओ।", "दुख ते दुख च-अल्लाह दुख गी खुशी कन्नै बदलदा ऐ।", "अल्लाह उंʼदी चिंता ते दुख गी दूर करदा ऐ ते उʼनें गी उंʼदी थाह्र पर खुशी दिंदा ऐ।"),
        "dua_difficulty_sahl" to DuaText("जिसलै किश औखी होंदी ऐ", "हे अल्लाह, किश बी सौखा नेईं ऐ छड़ा जेह्ड़ा तुस सौखा बनाओ, ते जे तुस चाह्न्नां तां औखे गी सौखा बनाओ।", "जिसलै किश औखी होंदी ऐ।", "परखें च आसानी ते औखे कम्म।"),
        "dua_musibah" to DuaText("आपदा पर (इस्तिरजा)", "हम अल्लाह दे न ते उसी पासे गै बापस जाईङन। ऐ अल्लाह, मेरे दुख-तकलीफ़ दा बदला मिगी देओ ते मेरे लेई एह्दे बदला च किश चंगा लाओ।", "कुसै बी नुकसान जां आपदा पर।", "अल्लाह निश्चत रूप कन्नै किश बेहतर दिंदा ऐ-उम्म सलाम (र) पैगंबर सल्लल्लाहु अलैहि वसल्लम दे हवाले कन्नै दित्ती गेई ही।"),
        "dua_debt" to DuaText("कर्ज थमां राहत आस्तै", "ऐ अल्लाह, तुंʼदे बरकत दे कारण मिगी तुंʼदे अलावा होर सभनें शा आज़ाद बनाओ ते तुंʼदे बरकत दे कारण तुस जेह्ड़ा बी वैध कीता ऐ, ओह्दे आस्तै मेरे लेई काफी करो।", "कर्ज चुकाने आस्तै-अली (आर. ए.) आसेआ सिखाया गेआ।", "जे कर्ज इक प्हाड़े जनेह् बी ऐ, तां बी अल्लाह इसगी चुकाई देग।"),
        "dua_anger" to DuaText("जिसलै गुस्साया जंदा ऐ", "में शापित शयतान शा अल्लाह दी शरण मंगदा आं।", "जिसलै गुस्साया जंदा ऐ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने आखेआ जे जे ओह् एह् आखङन तां उंʼदा गुस्सा दूर होई होग।"),
        "dua_waswasa" to DuaText("विश्वास च वासवास दे खलाफ", "में अल्लाह ते ओह्दे रसूलें च विश्वास करदा आं।", "जिसलै शैतान विश्वास दे बारे च फुसफुसांदा ऐ तां एह् होंदा ऐ।", "जिसलै फुसफुस आई, तां एह् दस्सो ते उसलै रुको (ते अल्लाह दी शरण बी लो)।"),
    )
}
